from scipy.optimize import least_squares
var=np.var(dP_dt)
forms={
 'hill2_Pmul': lambda p: -p[0]*t**2/(p[1]**2+t**2)*(1+p[2]*P) + p[3]*P + p[4]*P**2 + p[5]*P*t,
 'hill2_Psat': lambda p: -p[0]*t**2/(p[1]**2+t**2) + (p[2]*P + p[3]*P*t)/(1+p[4]*P),
 'exp_Psat': lambda p: -p[0]*(1-np.exp(-p[1]*t**p[2])) + (p[3]*P + p[4]*P*t)/(1+p[5]*P) + p[6]*P**2*np.exp(-p[7]*t),
 'logist_t': lambda p: -p[0]/(1+np.exp(-p[1]*(t-p[2]))) + p[3]*P + p[4]*P**2 + p[5]*P*t + p[6]*P**2*t,
 'hill2_Pquad_t': lambda p: -p[0]*t**2/(p[1]**2+t**2) + p[2]*P + p[3]*P**2 + p[4]*P*t + p[5]*P**2*t + p[6]*P*t**2,
}
for name,f in forms.items():
